// Builds the editor palette from a game checkout (Qlippoth Station or another SS14 fork).
//
//   npm run palette -- --game ../Qlippoth-station-14 [--out public/palette]
//
// Output (git-ignored, regenerated by CI):
//   palette.json   ids, names, layers, flags, atlas coordinates, the game's id renames (migration.yml)
//   atlas.png      one 32x32 icon per palette entry
//   credits.json   license/copyright of every sprite used
//
// The work itself is in src/palette-core.mjs, which the editor also runs in the browser for codebases added from a
// GitHub link. This script only gives it the files of the checkout.

import fs from "node:fs";
import path from "node:path";
import { execSync } from "node:child_process";
import YAML from "yaml";
import { PNG } from "pngjs";
import { buildPalette } from "../src/palette-core.mjs";

const arg = (name) => {
  const index = process.argv.indexOf(name);
  return index >= 0 ? process.argv[index + 1] : undefined;
};

const game = arg("--game") ?? process.env.QLIPPOTH_GAME_DIR;
if (!game) {
  console.error("Usage: npm run palette -- --game <path to a game checkout> [--out <folder>]");
  process.exit(1);
}
const resources = path.resolve(game, "Resources");
if (!fs.existsSync(path.join(resources, "Prototypes"))) {
  console.error(`No Resources/Prototypes under ${path.resolve(game)}`);
  process.exit(1);
}
const outDir = path.resolve(arg("--out") ?? "public/palette");

// Sorted listings, so the palette is the same on every file system.
function walk(dir) {
  if (!fs.existsSync(dir)) return [];
  const files = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true }).sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) files.push(...walk(full));
    else files.push(full);
  }
  return files;
}
const relative = (file) => path.relative(resources, file).split(path.sep).join("/");

// Some game sprites carry extra bytes after the IEND chunk. The game ignores them; pngjs refuses the file.
function trimAfterEnd(buffer) {
  let offset = 8;
  while (offset + 8 <= buffer.length) {
    const length = buffer.readUInt32BE(offset);
    const end = offset + 12 + length;
    if (buffer.toString("ascii", offset + 4, offset + 8) === "IEND") return buffer.subarray(0, end);
    offset = end;
  }
  return buffer;
}

const source = {
  list: async (dir) => walk(path.join(resources, dir)).map(relative),
  has: (file) => fs.existsSync(path.join(resources, file)),
  text: async (file) => {
    try {
      return fs.readFileSync(path.join(resources, file), "utf8");
    } catch {
      return null;
    }
  },
  image: async (file) => {
    try {
      const png = PNG.sync.read(trimAfterEnd(fs.readFileSync(path.join(resources, file))));
      return { width: png.width, height: png.height, data: png.data };
    } catch {
      return null;
    }
  },
};

function gameCommit() {
  try {
    return execSync("git rev-parse HEAD", { cwd: game, stdio: ["ignore", "pipe", "ignore"] }).toString().trim();
  } catch {
    return null;
  }
}

const { palette, atlas, credits, unreadable } = await buildPalette(source, YAML);

const png = new PNG({ width: atlas.width, height: atlas.height });
png.data = Buffer.from(atlas.data.buffer, atlas.data.byteOffset, atlas.data.byteLength);
fs.mkdirSync(outDir, { recursive: true });
fs.writeFileSync(path.join(outDir, "atlas.png"), PNG.sync.write(png));
fs.writeFileSync(path.join(outDir, "palette.json"), JSON.stringify({ ...palette, gameCommit: gameCommit() }));
fs.writeFileSync(path.join(outDir, "credits.json"), JSON.stringify(credits, null, 1));

for (const file of unreadable) console.warn(`Skipped unreadable YAML: Resources/${file}`);
const items = palette.items;
const count = (layer) => items.filter((item) => item.layer === layer).length;
const hidden = items.filter((item) => item.flags?.hidden).length;
const noIcon = items.filter((item) => item.icon === null).length;
console.log(
  `Palette: ${count("floor")} tiles, ${count("structure")} structures, ${count("object")} objects ` +
    `(${hidden} hidden from the palette list, ${noIcon} without a sprite) -> ${path.relative(process.cwd(), outDir).split(path.sep).join("/")}`
);
